mapper.select:
SELECT `risk_level` AS `riskLevel`, COUNT(1) AS `count` FROM `key_person` WHERE `deleted` = 0
AND `status` = #{status}
GROUP BY `risk_level`

SELECT `area_id` AS `areaId`, `area_name` AS `areaName`, COUNT(DISTINCT `supervisor_user_id`) AS `count` FROM `key_person` WHERE `deleted` = 0
AND `status` = #{status}
GROUP BY `area_id`, `area_name` ORDER BY `count` DESC, `area_name` ASC LIMIT #{limit}

SELECT `area_id` AS `areaId`, `area_name` AS `areaName`, COUNT(1) AS `count` FROM `key_person` WHERE `deleted` = 0 AND `risk_level` = 'HIGH'
AND `status` = #{status}
GROUP BY `area_id`, `area_name` ORDER BY `count` DESC, `area_name` ASC LIMIT #{limit}
